uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

uniform float u_speed;
uniform float u_camera_dist;
uniform float u_fov;
uniform float u_twist;
uniform float u_thickness;
uniform float u_glow_intensity;
uniform float u_wave_height;
uniform float u_wave_freq;
uniform float u_darkness;
uniform float u_color_saturation;
uniform float u_viscosity; // New control for the thickness of the "blood" surface

out vec4 fragColor;

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Higher quality hash for dithering
float noise(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float getCarpetWave(vec2 p) {
    float t = iTime * u_speed;
    // Modified wave to look more like thick liquid ripples
    float wave = sin(p.x * u_wave_freq + t) * cos(p.y * (u_wave_freq * 0.5) + t * 0.3);
    wave += (0.5 - u_viscosity * 0.3) * sin(p.x * u_wave_freq * 2.1 - t * 1.2);
    wave *= u_wave_height;
    return wave;
}

float map(vec3 p) {
    float t = iTime * u_speed * 0.5;
    float waveHeight = getCarpetWave(p.xz);
    float floorDist = p.y - waveHeight;
    float strands = 1e10;

    for(float i = 0.0; i < 3.0; i += 1.0) {
        float offset = i * 2.0;
        vec2 pathPoint = vec2(p.x, sin(p.x * 0.2 + t + offset) * 5.0);
        float pathWave = getCarpetWave(vec2(p.x, pathPoint.y));
        vec3 strandPos = vec3(p.x, pathWave + 0.5, pathPoint.y);
        vec3 q = p - strandPos;
        q.xz *= rot(p.x * u_twist + t);
        // Ribbon thickness modulated to look like arterial pulses
        float pulse = 0.5 + 0.3 * sin(p.x * 2.0 + t * 3.0);
        float ribbon = length(q.yz) - u_thickness * pulse;
        strands = smin(strands, ribbon, 1.2);
    }
    return smin(floorDist, strands, 0.8);
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.005, 0.0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    float globalTime = iTime * u_speed;

    vec3 ro = vec3(globalTime * 2.0, u_camera_dist, 0.0);
    float lookAheadX = ro.x + 5.0;
    float lookAtY = getCarpetWave(vec2(lookAheadX, 0.0)) * 0.5;
    vec3 ta = vec3(lookAheadX, lookAtY, 0.0);

    vec3 cw = normalize(ta - ro);
    vec3 cu = normalize(cross(cw, vec3(0, 1, 0)));
    vec3 cv = normalize(cross(cu, cw));
    vec3 rd = normalize(uv.x * cu + uv.y * cv + u_fov * cw);

    float t = 0.0, d = 0.0, glow = 0.0;
    vec3 col = vec3(0.0);

    for(int i = 0; i < 128; i++) {
        vec3 p = ro + rd * t;
        d = map(p);
        // Red glow for the "blood" atmosphere
        glow += (0.01 / (0.04 + d * d)) * (1.0 - u_darkness * 0.5);
        if(d < 0.001 || t > 60.0) break;
        t += d * 0.6; 
    }

    if(t < 60.0) {
        vec3 p = ro + rd * t;
        vec3 n = getNormal(p);
        vec3 ref = reflect(rd, n);
        float ao = clamp(0.5 + 0.5 * n.y, 0.0, 1.0);
        float fres = pow(1.0 + dot(rd, n), 4.0);

        // Deep Blood Red Palette
        vec3 bloodBase = vec3(0.4, 0.0, 0.01);
        vec3 bloodBright = vec3(0.9, 0.05, 0.05);
        vec3 palette = mix(bloodBase, bloodBright, 0.5 + 0.5 * cos(p.x * 0.1));

        vec3 baseCol = mix(vec3(0.01, 0.0, 0.0), palette, u_color_saturation);

        vec3 lp = ro + vec3(-5.0, 15.0, -5.0);
        vec3 ld = normalize(lp - p);
        float diff = pow(max(dot(n, ld), 0.0), 1.0 + u_darkness * 3.0);
        // High specular for a wet, bloody look
        float spec = pow(max(dot(ref, ld), 0.0), 30.0);

        col = baseCol * diff + (spec * 0.8) + (fres * bloodBright * 0.4);
        col *= ao;

        // Texture used for "coagulation" or cells detail
        vec3 tex = texture(iChannel0, p.xz * 0.1).rgb;
        col *= mix(vec3(1.0), vec3(tex.r * 1.5, tex.r * 0.2, tex.r * 0.2), 0.4);
    }

    // Crimson/Ruby glow
    vec3 glowCol = vec3(1.0, 0.0, 0.1) * (0.8 + 0.2 * sin(globalTime));
    col += glow * glowCol * u_glow_intensity;

    // Deep dark red fog
    vec3 fogColor = vec3(0.01, 0.0, 0.0);
    col = mix(col, fogColor, smoothstep(15.0, 60.0, t));

    // Dithering
    float dither = noise(gl_FragCoord.xy + iTime) / 255.0;
    col += dither;

    col = pow(col, vec3(0.9)); // Contrast for the organic look
    col = clamp(col, 0.0, 1.0);

    fragColor = vec4(col, 1.0);
}
